head.b:skin:
:root{color-scheme:dark;--bg:#090b12;--panel:#101521;--panel2:#151c2b;--ink:#f7f9ff;--muted:#9da8bc;--line:rgba(220,232,255,.12);--cyan:#63e5ff;--violet:#9b8cff;--green:#b4f7dc;--cream:#f2f0e8;--shadow:0 28px 90px #0005;--font:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;--display:ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}
:root[data-theme="light"]{color-scheme:light;--bg:#f4f7fb;--panel:#fff;--panel2:#edf2f8;--ink:#10182a;--muted:#5e6b80;--line:rgba(23,40,67,.12);--shadow:0 24px 70px #1f34521c}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:88px;-webkit-text-size-adjust:100%}body{margin:0;background:var(--bg);color:var(--ink);font:400 15px/1.7 var(--font);overflow-x:hidden;transition:background .3s,color .3s}a{color:inherit;text-decoration:none}button,input{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid var(--cyan);outline-offset:4px}.wrap{width:min(1240px,calc(100% - 48px));margin-inline:auto}
.topline{height:31px;border-bottom:1px solid var(--line);color:var(--muted);font-size:10px}.topline .wrap{height:100%;display:flex;align-items:center;justify-content:space-between;gap:12px}.topline strong{color:var(--ink);letter-spacing:.15em}.status{display:flex;align-items:center;gap:8px}.dot{width:6px;height:6px;border-radius:50%;background:var(--green);box-shadow:0 0 12px var(--green)}
.header{position:sticky;top:0;z-index:80;background:color-mix(in srgb,var(--bg) 82%,transparent);backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.nav{min-height:76px;display:flex;align-items:center;gap:24px}.brand{display:inline-flex;align-items:center;gap:10px;white-space:nowrap;font:850 22px/1 var(--display);letter-spacing:-.065em}.brand-mark{width:39px;height:39px;display:grid;place-items:center;border:1px solid #ffffff3b;border-radius:13px;background:linear-gradient(145deg,#63e5ff,#796bff);color:#07101a;box-shadow:0 8px 28px #63e5ff26;position:relative}.brand-word em{font-style:normal;color:var(--cyan)}.nav-links{display:flex;align-items:center;gap:clamp(12px,1.8vw,24px);margin-inline:auto}.nav-links a{color:var(--muted);font-size:12px;font-weight:650;white-space:nowrap}.nav-links a:hover{color:var(--ink)}.nav-actions{display:flex;align-items:center;gap:8px}.icon-btn{width:40px;height:40px;border:1px solid var(--line);border-radius:13px;background:var(--panel);color:var(--ink);display:grid;place-items:center;font-size:17px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:44px;padding:0 18px;border:1px solid transparent;border-radius:13px;white-space:nowrap;font-size:12px;font-weight:780;transition:transform .22s,background .22s,border-color .22s,box-shadow .22s}.btn-primary{background:var(--cyan);color:#06121b;box-shadow:0 9px 30px #63e5ff1c}.btn-primary:hover{background:#8cedff;transform:translateY(-2px);box-shadow:0 13px 32px #63e5ff30}.btn-ghost{border-color:var(--line);background:#ffffff08;color:var(--ink)}.btn-ghost:hover{border-color:#63e5ff88;background:#63e5ff12;transform:translateY(-2px)}.burger{display:none;width:40px;height:40px;border:1px solid var(--line);border-radius:13px;background:var(--panel);color:var(--ink);font-size:18px}.menu{display:none}
.hero{position:relative;isolation:isolate;min-height:610px;padding:64px 0 54px;overflow:hidden;border-bottom:1px solid var(--line);background:radial-gradient(ellipse at 76% 35%,#3d61962b,transparent 40%),radial-gradient(ellipse at 15% 10%,#5ce5ff12,transparent 35%),var(--bg)}.hero:before{content:"";position:absolute;inset:0;z-index:-2;opacity:.18;background-image:linear-gradient(var(--line) 1px,transparent 1px),linear-gradient(90deg,var(--line) 1px,transparent 1px);background-size:72px 72px;mask-image:linear-gradient(#000,transparent 95%)}.hero:after{content:"";position:absolute;inset:auto 0 -1px;height:110px;background:linear-gradient(transparent,var(--bg));z-index:-1}.hero-grid{display:grid;grid-template-columns:1.03fr .97fr;align-items:center;gap:35px;min-height:470px}.hero-copy{position:relative;z-index:2;max-width:630px}.eyebrow{display:inline-flex;align-items:center;gap:10px;color:var(--cyan);font-size:11px;font-weight:850;letter-spacing:1.5px;margin-bottom:20px}.eyebrow .dot{width:7px;height:7px}.hero h1{font-size:clamp(42px,5.25vw,76px);line-height:1.08;letter-spacing:-2.8px;margin:0 0 22px;font-weight:880}.hero h1 .line{display:block;overflow:hidden;padding-block:2px}.hero h1 em{font-style:normal;background:linear-gradient(105deg,#fff 8%,var(--cyan) 48%,#b6aaff 92%);-webkit-background-clip:text;background-clip:text;color:transparent}.hero-lede{max-width:545px;color:var(--muted);font-size:15px;line-height:1.95;margin:0 0 28px}.hero-actions{display:flex;gap:12px;flex-wrap:wrap}.hero-proof{display:flex;gap:18px;flex-wrap:wrap;margin-top:28px;color:var(--muted);font-size:11px}.hero-proof span:first-child:before{content:"";display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--green);box-shadow:0 0 12px var(--green);margin-inline-end:7px}
.art{position:relative;min-height:440px;display:grid;place-items:center;perspective:900px}.art-glow{position:absolute;width:76%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle,#63e5ff30,#6872ff12 43%,transparent 70%);filter:blur(12px);animation:glowPulse 7s ease-in-out infinite alternate}.core{position:relative;width:min(58%,290px);aspect-ratio:1;border-radius:50%;overflow:hidden;background:radial-gradient(circle at 28% 23%,#a0f3ff 0,#326d99 13%,#142e4e 37%,#101628 67%,#080b14 100%);box-shadow:inset -25px -16px 40px #030710cc,inset 10px 7px 28px #8aefff4a,0 0 70px #42d9ff20;animation:globeFloat 8s ease-in-out infinite}.core:before{content:"";position:absolute;inset:-3%;border-radius:50%;background:repeating-linear-gradient(0deg,transparent 0 20px,#92efff34 21px 22px,transparent 23px 38px);transform:rotate(-17deg) scaleX(.83);animation:globeDrift 18s linear infinite}.core:after{content:"";position:absolute;inset:0;border-radius:50%;background:repeating-linear-gradient(90deg,transparent 0 25px,#a7f5ff35 26px 27px,transparent 28px 52px);mask-image:radial-gradient(ellipse,#000 50%,transparent 72%);transform:rotate(18deg);animation:globeDrift 22s linear infinite reverse}.land-shape{position:absolute;inset:15% 8%;border-radius:48% 42% 57% 36%;background:linear-gradient(140deg,#b4f7dc55,#8cf0ff08 58%,#8f8bff35);clip-path:polygon(13% 12%,30% 5%,38% 22%,55% 17%,62% 33%,51% 43%,69% 52%,61% 69%,47% 67%,37% 85%,23% 74%,19% 55%,4% 41%);filter:blur(1px)}.orbit{position:absolute;border:1px solid #75e2ff59;border-radius:50%;width:90%;height:36%;transform:rotate(-26deg);animation:orbitTurn 15s linear infinite}.orbit:after{content:"";position:absolute;left:14%;top:11%;width:9px;height:9px;border-radius:50%;background:var(--cyan);box-shadow:0 0 20px var(--cyan)}.orbit-two{width:105%;height:51%;transform:rotate(48deg);border-color:#a69cff3a;animation-duration:22s;animation-direction:reverse}.orbit-three{width:120%;height:65%;transform:rotate(74deg);border-style:dashed;border-color:#8af0ff21;animation-duration:30s}.art-label{position:absolute;right:9%;bottom:2%;font-size:10px;letter-spacing:2px;color:var(--muted)}.glass-card{position:absolute;z-index:3;border:1px solid #c2f5ff28;background:rgba(12,20,34,.79);backdrop-filter:blur(18px);border-radius:17px;padding:14px 16px;box-shadow:0 18px 60px #0003;color:#f7f9ff;animation:floatPanel 6s ease-in-out infinite}.glass-card .symbol{float:right;color:var(--cyan);font-size:18px;margin-inline-start:10px}.glass-kicker{color:#9aaec5;font-size:10px;margin-bottom:5px}.glass-title{font-size:13px;font-weight:800;letter-spacing:-.2px}.glass-meta{font-size:10px;color:#9aaec5;margin-top:4px}.glass-card.top{top:10%;right:0}.glass-card.bottom{bottom:10%;left:0;animation-delay:-2s}
.wisdom-section{padding:28px 0 0}.wisdom-card{position:relative;display:flex;align-items:center;gap:17px;padding:18px 22px;border:1px solid #9d91ff35;border-radius:18px;background:linear-gradient(115deg,#63e5ff12,#9b8cff18),var(--panel);overflow:hidden}.wisdom-mark{flex:0 0 44px;width:44px;height:44px;border-radius:15px;display:grid;place-items:center;background:#9b8cff1c;color:var(--violet);font-size:23px}.wisdom-kicker{color:var(--cyan);font-weight:850;font-size:10px;letter-spacing:1px}.wisdom-text{margin:3px 0;font-size:14px;font-weight:700}.wisdom-sub{color:var(--muted);font-size:11px}.wisdom-day{margin-inline-start:auto;color:var(--muted);font-size:10px;white-space:nowrap}
.section{padding:66px 0}.section-head{display:flex;justify-content:space-between;align-items:end;gap:25px;margin-bottom:25px}.section-kicker{color:var(--cyan);font-size:11px;font-weight:850;letter-spacing:1.5px;margin-bottom:9px}.section-head h2{font-size:clamp(28px,3.3vw,42px);line-height:1.2;letter-spacing:-1.4px;margin:0;font-weight:850}.section-head p{max-width:520px;color:var(--muted);font-size:13px;margin:12px 0 0}.count-pill{display:flex;align-items:baseline;gap:7px;padding:10px 14px;border:1px solid var(--line);border-radius:14px;background:var(--panel);white-space:nowrap}.count-pill strong{color:var(--cyan);font-size:21px}.count-pill span{font-size:11px;color:var(--muted)}.searchbar{display:flex;gap:9px;margin-bottom:14px}.searchbar input{flex:1;min-width:0;height:49px;border:1px solid var(--line);border-radius:14px;background:var(--panel);color:var(--ink);padding:0 16px;outline:none}.searchbar input:focus{border-color:#63e5ff99;box-shadow:0 0 0 4px #63e5ff0d}.searchbar button{border:0;border-radius:13px;padding:0 22px;background:var(--cyan);color:#06121b;font-weight:850;font-size:12px}.categories{display:flex;gap:8px;overflow-x:auto;padding:2px 1px 12px;margin-bottom:7px;scrollbar-width:thin}.ur-category{white-space:nowrap;border:1px solid var(--line);border-radius:999px;padding:8px 13px;background:transparent;color:var(--muted);font-size:11px}.ur-category:hover,.ur-category.active{background:#63e5ff13;border-color:#63e5ff70;color:var(--cyan)}#to-live-count{font-size:11px;color:var(--muted);margin:0 0 14px}.ur-tool-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}.ur-card{min-width:0;min-height:172px;position:relative;display:flex;flex-direction:column;padding:17px;border:1px solid var(--line);border-radius:17px;background:linear-gradient(150deg,var(--panel),#ffffff02);overflow:hidden;transition:transform .25s,border-color .25s,box-shadow .25s}.ur-card[hidden]{display:none!important}.ur-card:before{content:"";position:absolute;width:120px;height:120px;border-radius:50%;background:radial-gradient(circle,#63e5ff12,transparent 70%);top:-62px;left:-42px;transition:transform .35s}.ur-card:hover{transform:translateY(-5px);border-color:#63e5ff64;box-shadow:0 20px 45px #00018}.ur-card:hover:before{transform:scale(1.6)}.ur-card-top{display:flex;align-items:center;justify-content:space-between;gap:10px}.ur-icon{display:grid;place-items:center;width:38px;height:38px;border-radius:13px;background:linear-gradient(140deg,#63e5ff1e,#9b8cff1c);border:1px solid #9eeeff1d;color:var(--cyan);font-size:17px;font-weight:850}.ur-tag{font-size:9px;letter-spacing:.6px;color:var(--muted);text-transform:uppercase}.ur-card h3{font-size:13px;line-height:1.45;margin:16px 0 7px;font-weight:800}.ur-card p{font-size:10px;line-height:1.8;color:var(--muted);margin:0 0 17px}.ur-card-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:auto;padding-top:9px;border-top:1px solid var(--line);font-size:10px;color:var(--cyan);font-weight:750}.ur-card-foot small{font-size:9px;color:var(--muted);font-weight:500}.ur-card-foot span{transition:transform .2s}.ur-card-foot:hover span{transform:translateX(-2px)}
.ai-section,.assistant-section{padding:0 0 70px}.ai-card,.ai-band{display:grid;grid-template-columns:1fr auto;align-items:center;gap:24px;padding:34px 36px;border-radius:24px;background:linear-gradient(110deg,#14263a,#182039 57%,#242045);border:1px solid #94eaff20;box-shadow:var(--shadow);color:#f7f9ff}.ai-card h2,.ai-band h2{font-size:clamp(23px,3vw,34px);line-height:1.25;margin:0 0 9px}.ai-card p,.ai-band p{margin:0;color:#b7c6da;font-size:12px;max-width:650px}.ai-card .btn,.ai-band .btn{white-space:nowrap;background:var(--cream);color:#111827}
.footer{padding:35px 0 22px;border-top:1px solid var(--line);background:var(--panel)}.footer-inner{display:flex;align-items:start;justify-content:space-between;gap:30px;padding-bottom:25px}.footer p{max-width:350px;color:var(--muted);font-size:11px;line-height:1.9}.footer-links{display:flex;flex-wrap:wrap;gap:13px 22px;color:var(--muted);font-size:11px}.footer-links a:hover{color:var(--cyan)}.footer-bottom{border-top:1px solid var(--line);padding-top:16px;display:flex;justify-content:space-between;gap:12px;color:var(--muted);font-size:10px}.footer-bottom strong{color:var(--ink)}
.page-shell{min-height:65vh;padding:35px 0 75px}.page-shell .back-home{margin-bottom:20px;font-size:12px;color:var(--cyan)}.page-shell .widget-content,.page-shell .post-body,.page-shell .post{max-width:920px;margin-inline:auto}.page-shell .post-body{line-height:1.9}.page-shell h1,.page-shell h2{line-height:1.35}.page-shell img{max-width:100%;height:auto}.page-shell input,.page-shell textarea,.page-shell select{max-width:100%}.page-shell .Blog{border:1px solid var(--line);background:var(--panel);border-radius:20px;padding:clamp(18px,4vw,40px)}
.anim .reveal{opacity:0;transform:translateY(22px);animation:riseIn .7s cubic-bezier(.2,.7,.2,1) forwards;animation-delay:var(--delay,0ms)}.anim.go .hero-copy .eyebrow{animation:riseIn .6s ease .25s both}.anim.go .hero h1 .line:nth-child(1){animation:lineUp .75s cubic-bezier(.2,.7,.2,1) .35s both}.anim.go .hero h1 .line:nth-child(2){animation:lineUp .8s cubic-bezier(.2,.7,.2,1) .55s both}.anim.go .art{animation:riseIn .9s cubic-bezier(.2,.7,.2,1) .4s both}.anim.go .btn-primary{animation:pillIn .7s cubic-bezier(.2,.7,.2,1) 1.1s both}.anim.go .btn-ghost{animation:pillIn .7s cubic-bezier(.2,.7,.2,1) 1.3s both}.anim.go .ur-card{animation:riseIn .65s ease both;animation-delay:calc(1.25s + var(--delay,0ms))}.anim.go .wisdom-card{animation:riseIn .7s ease 1.6s both}.anim.go .footer{animation:riseIn .7s ease 1.7s both}
@keyframes riseIn{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:translateY(0)}}@keyframes lineUp{from{opacity:0;transform:translateY(34px);clip-path:inset(0 0 100% 0)}to{opacity:1;transform:translateY(0);clip-path:inset(0)}}@keyframes pillIn{from{opacity:0;transform:translateY(14px) scale(.97)}to{opacity:1;transform:translateY(0) scale(1)}}@keyframes globeFloat{0%,100%{transform:translateY(0) rotate(-5deg)}50%{transform:translateY(-12px) rotate(4deg)}}@keyframes orbitTurn{to{rotate:360deg}}@keyframes globeDrift{to{background-position:0 80px}}@keyframes glowPulse{from{transform:scale(.94);opacity:.7}to{transform:scale(1.08);opacity:1}}@keyframes floatPanel{0%,100%{translate:0 0}50%{translate:0 -9px}}
@media(max-width:1080px){.nav-links{gap:13px}.hero-grid{gap:5px}.ur-tool-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.art{min-height:380px}.hero h1{font-size:clamp(42px,5.5vw,64px)}}
@media(max-width:760px){.wrap{width:min(100% - 30px,620px)}.topline{height:29px}.status{font-size:9px}.nav{min-height:67px}.nav-links{display:none}.burger{display:grid;place-items:center}.menu{position:absolute;top:calc(100% + 8px);left:15px;right:15px;padding:12px;border:1px solid var(--line);border-radius:17px;background:var(--panel);box-shadow:var(--shadow);flex-direction:column;gap:0}.menu.open{display:flex}.menu a{padding:11px 10px;border-bottom:1px solid var(--line);font-size:12px;color:var(--muted)}.menu a:last-child{border:0}.nav-actions .btn{display:none}.hero{padding:35px 0 32px;min-height:auto}.hero-grid{grid-template-columns:1fr;gap:0}.hero-copy{order:1}.art{order:0;min-height:280px;margin-bottom:6px}.core{width:min(60%,210px)}.glass-card{padding:10px 12px}.glass-title{font-size:11px}.glass-meta{font-size:9px}.glass-card.top{right:-2%;top:6%}.glass-card.bottom{left:-1%;bottom:6%}.art-label{right:12%;bottom:0}.hero h1{font-size:clamp(39px,10vw,58px);letter-spacing:-1.7px;margin-bottom:14px}.hero-lede{font-size:13px;margin-bottom:21px}.hero-proof{margin-top:21px;gap:11px}.wisdom-section{padding-top:18px}.wisdom-card{padding:14px;gap:11px}.wisdom-text{font-size:12px}.wisdom-day{display:none}.section{padding:48px 0}.section-head{display:block}.section-head h2{font-size:30px}.count-pill{display:inline-flex;margin-top:16px}.searchbar{gap:7px}.searchbar button{padding:0 15px}.ur-tool-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.ur-card{padding:12px;border-radius:15px}.ur-card h3{font-size:12px;margin-top:13px}.ur-card p{font-size:10px}.ur-icon{width:34px;height:34px}.ur-card-foot{font-size:9px}.ur-card-foot small{display:none}.ai-section,.assistant-section{padding-bottom:50px}.ai-card,.ai-band{grid-template-columns:1fr;padding:24px 21px}.ai-card .btn,.ai-band .btn{justify-self:start}.footer-inner{display:block}.footer-links{margin-top:18px}.footer-bottom{flex-direction:column}.page-shell{padding:22px 0 50px}}
@media(max-width:380px){.brand{font-size:18px}.brand-mark{width:32px;height:32px}.hero h1{font-size:36px}.ur-tool-grid{gap:7px}.ur-card{padding:10px}.ur-card h3{font-size:11px}.ur-card p{font-size:9px}.nav-actions{gap:5px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}.anim .reveal,.anim.go .hero-copy .eyebrow,.anim.go .hero h1 .line,.anim.go .art,.anim.go .btn-primary,.anim.go .btn-ghost{opacity:1;transform:none;clip-path:none;animation:none!important}.core,.orbit,.art-glow,.glass-card{animation:none!important}}

body.script:
(function(){var root=document.documentElement;if(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;root.classList.add('anim');var bootTimer=0,started=false,cleaned=false,safety=0;function clean(){if(cleaned)return;cleaned=true;clearTimeout(safety);root.removeEventListener('animationend',onEnd,true);root.classList.remove('anim','go')}function onEnd(e){if(e.animationName==='pillIn'&&e.target.classList.contains('btn-ghost'))clean()}function start(){if(started||cleaned)return;started=true;clearTimeout(bootTimer);root.addEventListener('animationend',onEnd,true);safety=setTimeout(clean,2600);root.classList.add('go')}function boot(){bootTimer=setTimeout(start,900);if(document.fonts&&document.fonts.ready&&typeof document.fonts.ready.then==='function')document.fonts.ready.then(start,start);else start()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot()})();
(function(){var burger=document.getElementById('burger'),menu=document.getElementById('menu');if(!burger||!menu)return;function set(open){menu.classList.toggle('open',open);burger.setAttribute('aria-expanded',String(open));burger.setAttribute('aria-label',open?'Close menu':'Open menu');burger.textContent=open?'×':'☰'}burger.addEventListener('click',function(e){e.stopPropagation();set(!menu.classList.contains('open'))});menu.addEventListener('click',function(e){if(e.target.closest('a'))set(false)});document.addEventListener('click',function(e){if(menu.classList.contains('open')&&!menu.contains(e.target)&&!burger.contains(e.target))set(false)});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&menu.classList.contains('open')){set(false);burger.focus()}})})();
(function(){var root=document.documentElement,cards=Array.from(document.querySelectorAll('#ur-tool-grid .ur-card')),cats=document.getElementById('to-categories'),input=document.getElementById('to-search'),form=document.getElementById('to-search-form'),empty=document.getElementById('to-empty'),count=document.getElementById('to-result-count'),live=document.getElementById('to-live-count'),langBtn=document.getElementById('ur-language'),themeBtn=document.getElementById('ur-theme'),language='ar',active='All',query='';try{language=localStorage.getItem('utilityra-language')||'ar'}catch(e){}function tr(ar,en){return language==='ar'?ar:en}function norm(v){return String(v||'').toLocaleLowerCase(language==='ar'?'ar':'en').normalize('NFKC')}function label(cat){if(cat==='All')return tr('كل الأدوات','All tools');var c=cards.find(x=>x.dataset.cat===cat);return c&&language==='ar'?(c.dataset.arCat||cat):cat}function renderCats(){if(!cats)return;cats.textContent='';['All',...new Set(cards.map(c=>c.dataset.cat).filter(Boolean))].forEach(cat=>{var b=document.createElement('button');b.type='button';b.className='ur-category'+(cat===active?' active':'');b.textContent=label(cat);b.setAttribute('aria-pressed',String(cat===active));b.addEventListener('click',function(){active=cat;renderCats();filter()});cats.appendChild(b)})}function filter(){var n=0;cards.forEach(c=>{var ok=(active==='All'||c.dataset.cat===active)&&(!query||norm((c.dataset.search||'')+' '+c.textContent+' '+c.dataset.id).includes(norm(query)));c.hidden=!ok;if(ok)n++});if(empty)empty.hidden=n>0;if(count)count.textContent=String(n);if(live)live.textContent=tr('عرض '+n+' من '+cards.length+' أداة','Showing '+n+' of '+cards.length+' tools')}function lang(v){language=v==='en'?'en':'ar';root.lang=language;root.dir=language==='ar'?'rtl':'ltr';document.querySelectorAll('[data-en],[data-ar]').forEach(el=>{var val=el.getAttribute('data-'+language);if(val!==null)el.textContent=val});document.querySelectorAll('[data-en-placeholder],[data-ar-placeholder]').forEach(el=>{var val=el.getAttribute('data-'+language+'-placeholder');if(val!==null)el.placeholder=val});if(input)input.placeholder=tr('ابحث عن أداة: PDF، كلمات، درجات، JSON…','Search tools: PDF, text, grades, JSON…');if(langBtn)langBtn.textContent=tr('EN','عربي');try{localStorage.setItem('utilityra-language',language)}catch(e){}renderCats();filter()}if(langBtn)langBtn.addEventListener('click',()=>lang(language==='ar'?'en':'ar'));var theme='dark';try{theme=localStorage.getItem('utilityra-theme')||'dark'}catch(e){}function setTheme(v){theme=v==='light'?'light':'dark';root.dataset.theme=theme;if(themeBtn){themeBtn.textContent=theme==='dark'?'☼':'◐';themeBtn.setAttribute('aria-label',theme==='dark'?'Switch to light mode':'Switch to dark mode')}try{localStorage.setItem('utilityra-theme',theme)}catch(e){}}if(themeBtn)themeBtn.addEventListener('click',()=>setTheme(theme==='dark'?'light':'dark'));setTheme(theme);if(input)input.addEventListener('input',()=>{query=input.value.trim();filter()});function track(type,tool,term){var base=window.UTILITYRA_API_BASE||'';if(!base)return;var params=new URLSearchParams(location.search),exclude=false;try{exclude=localStorage.getItem('utilityra-owner-exclude')==='1'||localStorage.getItem('utilityra-review-mode')==='1'}catch(e){}if(exclude||params.has('utilityra_review')||params.has('review')||params.has('ai_review')||navigator.webdriver||/bot|crawler|spider|headless|lighthouse|pagespeed/i.test(navigator.userAgent)||location.pathname.startsWith('/admin'))return;var key='';try{key=localStorage.getItem('utilityra-visitor-key')||'';if(!/^[a-zA-Z0-9-]{16,80}$/.test(key)){key=crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(24))).map(x=>x.toString(16).padStart(2,'0')).join('');localStorage.setItem('utilityra-visitor-key',key)}}catch(e){return}fetch(base.replace(/\/$/,'')+'/api/analytics/event',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({visitorKey:key,eventType:type,path:location.pathname,referrer:document.referrer,toolKey:tool||'',searchTerm:term||'',reviewMode:false}),keepalive:true}).catch(()=>{})}if(form)form.addEventListener('submit',function(e){e.preventDefault();query=input?input.value.trim():'';filter();track(cards.some(c=>!c.hidden)?'search':'search_miss','',query);document.getElementById('tools')?.scrollIntoView({behavior:window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})});cards.forEach(c=>{var a=c.querySelector('.ur-card-foot');if(a)a.addEventListener('click',()=>track('tool_open',c.dataset.id,''))});if(cards.length)track('page_view','','');lang(language)})();
 (function(){var text=document.getElementById('utilityra-wisdom-text'),day=document.getElementById('utilityra-wisdom-day');if(!text||!day)return;var quotes=[{ar:'الخطوات الصغيرة المستمرة تصنع فرقًا كبيرًا.',en:'Small, consistent steps create meaningful change.',subAr:'ابدأ بمهمة واحدة، وأنهِها بإتقان.',subEn:'Start with one task, and finish it with care.'},{ar:'التعلّم استثمار يعود نفعه كل يوم.',en:'Learning is an investment that pays every day.',subAr:'خصص وقتًا قصيرًا اليوم لتتعلم شيئًا جديدًا.',subEn:'Set aside a little time today to learn something new.'},{ar:'الوضوح أول خطوة نحو الحل.',en:'Clarity is the first step toward a solution.',subAr:'قسّم المشكلة الكبيرة إلى خطوات بسيطة.',subEn:'Break a large problem into smaller, clear steps.'},{ar:'الإتقان عادة تبدأ بالاهتمام بالتفاصيل.',en:'Excellence begins with care for the details.',subAr:'راجع عملك مرة إضافية قبل أن تنهيه.',subEn:'Give your work one thoughtful review before finishing.'},{ar:'الاستمرار أهم من انتظار اللحظة المثالية.',en:'Consistency matters more than waiting for the perfect moment.',subAr:'أنجز ما تستطيع اليوم بما تملكه الآن.',subEn:'Do what you can today with what you have now.'},{ar:'المعرفة تصبح قوة عندما تتحول إلى عمل.',en:'Knowledge becomes powerful when put into action.',subAr:'طبّق فكرة واحدة مما تعلمته.',subEn:'Put one thing you learned into practice.'},{ar:'الوقت الذي تستثمره في التنظيم يوفر عليك الجهد.',en:'Time spent organizing saves effort later.',subAr:'رتّب مهمتك التالية قبل أن تبدأ.',subEn:'Organize your next task before you begin.'}];var now=new Date(),start=new Date(now.getFullYear(),0,0),index=Math.floor((now-start)/86400000)%quotes.length,q=quotes[index],lang=document.documentElement.lang==='en'?'en':'ar';function render(){lang=document.documentElement.lang==='en'?'en':'ar';text.textContent=q[lang];var sub=document.querySelector('#utilityra-wisdom .wisdom-sub');if(sub)sub.textContent=q[lang==='en'?'subEn':'subAr'];day.textContent=lang==='en'?'DAILY INSPIRATION':'حكمة اليوم · '+now.toLocaleDateString('ar-EG',{day:'numeric',month:'short'});}render();var langButton=document.getElementById('lang-toggle')||document.getElementById('langBtn')||document.querySelector('[data-action=language]');if(langButton)langButton.addEventListener('click',function(){setTimeout(render,0);});var observer=new MutationObserver(render);observer.observe(document.documentElement,{attributes:true,attributeFilter:['lang']});})();
